 if(wireStart){const c=project.components.find(c=>c.id===wireStart.id);if(c){const target=wireTarget(),wire=target?null:wireHit(),end=target?target.position:wire?wire.point:{x:snap(pointer.x),y:snap(pointer.y)},points=wireRoute(terminal(c,wireStart.port),end,wirePoints);html=`<path d="${pathString(points)}" fill="none" stroke="#2199b8" stroke-width="2" stroke-dasharray="5 4" pointer-events="none"/><circle cx="${end.x}" cy="${end.y}" r="5" fill="#2199b8" opacity=".3"/>`;}}

