async function exportSVG(){const clone=$('#canvas').cloneNode(true);clone.setAttribute('xmlns','http://www.w3.org/2000/svg');clone.setAttribute('viewBox','0 0 1200 840');clone.setAttribute('width','1200');clone.setAttribute('height','840');clone.querySelector('#world').removeAttribute('transform');clone.querySelector('#overlay').remove();clone.querySelectorAll('.selection-box,.wire-hit,.port-hit,title').forEach(n=>n.remove());const css='<style>'+await fetch('./native.css').then(r=>r.text())+'</style>';download(`${fileName()}.svg`,new XMLSerializer().serializeToString(clone).replace('</defs>',`${css}</defs>`),'image/svg+xml');notify('Diagrama SVG exportado.');}
async function confirmReplace(title){$('#confirm-title').textContent=title;$('#confirm-dialog').showModal();return new Promise(resolve=>{const finish=result=>{$('#confirm-dialog').close();$('#confirm-yes').onclick=null;$('#confirm-cancel').onclick=null;resolve(result);};$('#confirm-yes').onclick=()=>finish(true);$('#confirm-cancel').onclick=()=>finish(false);$('#confirm-dialog').oncancel=()=>finish(false);});}
