$('#file-input').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>3_000_000)return notify('Arquivo muito grande. Limite de 3 MB.');try{const parsed=validateProject(JSON.parse(await file.text()));if(!await confirmReplace('Abrir projeto salvo?'))return;snapshot();project=parsed;selected=null;stop(false);$('#project-name').value=project.name;changed();fit();notify('Projeto aberto com sucesso.');}catch(error){notify(error.message||'Não foi possível abrir este projeto.');}});
const help=()=>$('#help-dialog').showModal();$('#help').onclick=help;$('#guide-button').onclick=help;$$('#help-dialog .dialog-close').forEach(b=>b.onclick=()=>$('#help-dialog').close());
document.addEventListener('keydown',e=>{if(e.target.matches('input,select,textarea')||$('dialog[open]'))return;const key=e.key.toLowerCase(),mod=e.ctrlKey||e.metaKey;if(key==='escape'){placing=null;wireStart=null;wirePoints=[];selected=null;pickTool('select');renderProperties();draw();return;}if(mod&&key==='s'){e.preventDefault();exportJSON();}else if(mod&&key==='z'){e.preventDefault();e.shiftKey?redo():undo();}else if(mod&&key==='y'){e.preventDefault();redo();}else if(mod&&key==='d'){e.preventDefault();duplicate();}else if(mod&&key==='c'){if(current()){clipboard={...current()};notify('Componente copiado.');}}else if(mod&&key==='v'&&clipboard&&!running){e.preventDefault();snapshot();const copy={...clipboard,id:uid(),tag:clipboard.type.startsWith('contact')?clipboard.tag:nextTag(clipboard.type),...placement(clipboard.type,{x:clipboard.x+40,y:clipboard.y+40},clipboard.rotation)};project.components.push(copy);selected=copy.id;changed();}else if(key===' '){e.preventDefault();run();}else if(key==='v')pickTool('select');else if(key==='w')pickTool('wire');else if(key==='h')pickTool('pan');else if(key==='r')rotate();else if(key==='delete'||key==='backspace'){e.preventDefault();deleteSelected();}else if(key==='/'){e.preventDefault();$('#search').focus();}else if(key==='+'||key==='=')zoom(1.2);else if(key==='-')zoom(1/1.2);else if(key==='0')fit();});

// Reconstructed command routing, IDs observed in the original PE resources.
function copySelection(){if(current()){clipboard={...current()};notify('Componente copiado.');}}
function pasteSelection(){if(!clipboard||running)return;snapshot();const c={...clipboard,id:uid(),tag:clipboard.type.startsWith('contact')?clipboard.tag:nextTag(clipboard.type),...placement(clipboard.type,{x:clipboard.x+40,y:clipboard.y+40},clipboard.rotation)};project.components.push(c);selected=c.id;changed();}
$('#copy').onclick=copySelection;$('#cut').onclick=()=>{copySelection();deleteSelected();};$('#paste').onclick=pasteSelection;
$('#pause').onclick=()=>{if(running){paused=true;release();updateControls();renderMonitor();}};
$('#single-step').onclick=()=>{if(!running)run();paused=true;step(.1);};
$$('.property-close').forEach(b=>b.onclick=()=>showSidebar('library'));
$('#monitor-toggle').onclick=()=>$('#monitor-dialog').show();$('#monitor-close').onclick=()=>$('#monitor-dialog').close();
const commands={57600:()=>loadExample('blank'),57601:()=>$('#file-input').click(),57603:exportJSON,57604:exportJSON,57607:()=>window.print(),33041:exportSVG,57643:undo,57644:redo,57634:copySelection,57635:()=>{copySelection();deleteSelected();},57637:pasteSelection,32773:()=>zoom(1.2),32778:()=>zoom(1/1.2),32776:fit,32772:()=>{view.scale=1;view.x=10;view.y=10;applyView();},32777:()=>$('#grid-toggle').click(),32971:()=>$('#run').click(),32972:()=>stop(),32974:()=>$('#pause').click(),32975:()=>$('#single-step').click(),57664:help,32785:draw};
const barCommands={32977:32868,32978:32856,32979:32857,32980:32824,32981:32809,33010:33001,32985:32825,32983:32931,33029:33030,32984:32826,33265:33265,33071:33068,33280:33279,33087:33081,33110:33107,33244:33241};
commands[32986]=()=>pickTool('wire');
for(const [cmd,cat] of Object.entries(barCommands))commands[cmd]=()=>{nativeCategory=cat;renderCatalog();};
const menus=nativeUI.menus[0]?.children?nativeUI.menus:(nativeUI.menus.find(m=>m.index===326)?.items||[]);
$('#native-menu').innerHTML=menus.map(m=>'<details><summary>'+esc(m.text.replaceAll('&',''))+'</summary><div class="dropdown">'+m.children.map(c=>{if(!c.command)return '<hr>';const [label,key]=c.text.replaceAll('&','').split('\t');return '<button data-native-action="'+c.command+'" '+(commands[c.command]?'':'disabled title="Ainda não implementado"')+'><span>'+esc(label)+'</span><kbd>'+esc(key||'')+'</kbd></button>';}).join('')+'</div></details>').join('');
$('#native-menu').onclick=e=>{const b=e.target.closest('[data-native-action]');if(b){commands[b.dataset.nativeAction]?.();$$('#native-menu details').forEach(d=>d.open=false);}};
$$('#native-menu details').forEach(d=>d.addEventListener('toggle',()=>{if(d.open)$$('#native-menu details').filter(x=>x!==d).forEach(x=>x.open=false);}));
document.addEventListener('pointerdown',e=>{if(!e.target.closest('#native-menu'))$$('#native-menu details').forEach(d=>d.open=false);});
const drawingCommands={32785:'select',32786:'line',32787:'rect',32788:'ellipse',32789:'rectFill',32790:'ellipseFill',32793:'text'};$('#native-drawing-tools').innerHTML=nativeToolbar(159).map(id=>'<button class="icon-button" '+(drawingCommands[id]?'data-draw-tool="'+drawingCommands[id]+'"':'disabled')+' title="'+esc(nativeLabel(id)+(drawingCommands[id]?'':' — ainda não implementado'))+'">'+icon(id)+'</button>').join('');
$('#native-drawing-tools').onclick=e=>{const b=e.target.closest('[data-draw-tool]');if(b){pickTool(b.dataset.drawTool);$$('[data-draw-tool]').forEach(x=>x.classList.toggle('selected',x===b));}};for(const [id,t]of Object.entries(drawingCommands))commands[id]=()=>pickTool(t);$$('[data-native-action]').forEach(b=>{if(commands[b.dataset.nativeAction]){b.disabled=false;b.removeAttribute('title');}});
const palette=['#000000','#ffffff','#808080','#c0c0c0','#800000','#ff0000','#808000','#ffff00','#008000','#00ff00','#008080','#00ffff','#000080','#0000ff','#800080','#ff00ff'];
$('#color-palette').innerHTML=palette.map(c=>'<button data-color="'+c+'" style="background:'+c+'" title="Cor '+c+'" aria-label="Cor '+c+'"></button>').join('');
$('#color-palette').onclick=e=>{const b=e.target.closest('[data-color]');if(!b)return;drawColor=b.dataset.color;$$('[data-color]').forEach(x=>x.classList.toggle('active',x===b));if((current()||getDrawing())&&!running){snapshot();(current()||getDrawing()).color=drawColor;changed();}};

let textPosition={x:100,y:100};
$('#text-cancel').onclick=()=>$('#text-dialog').close();$('#text-form').onsubmit=e=>{e.preventDefault();const text=$('#drawing-text').value.trim();if(text){snapshot();const d={id:uid(),kind:'text',...textPosition,text,color:drawColor,fontSize:16};(project.drawings??=[]).push(d);selected=d.id;changed();}$('#text-dialog').close();$('#drawing-text').value='';};
let last=performance.now();setInterval(()=>{const now=performance.now(),dt=Math.min((now-last)/1000,.25);last=now;if(running&&!paused&&window.labActive!==false&&!document.hidden)step(dt);},100);
new ResizeObserver(()=>fit()).observe($('#viewport'));
$('#project-name').value=project.name;renderCatalog();draw();renderProperties();renderMonitor();updateControls();requestAnimationFrame(fit);

function showSidebar(tab){
 $('#properties-dialog').hidden=tab!=='properties';$('#command-library').hidden=tab!=='library';
 $('#tab-properties').setAttribute('aria-pressed',String(tab==='properties'));$('#tab-library').setAttribute('aria-pressed',String(tab==='library'));
}
$('#tab-properties').onclick=()=>showSidebar('properties');$('#tab-library').onclick=()=>showSidebar('library');
$('#toggle-sidebar').onclick=()=>{
 const collapsed=!$('#command-sidebar').hidden;
 $('#command-sidebar').hidden=collapsed;
 $('.workspace').classList.toggle('sidebar-collapsed',collapsed);
 $('#toggle-sidebar').setAttribute('aria-expanded',String(!collapsed));
 $('#toggle-sidebar').textContent=collapsed?'« Mostrar lateral':'Minimizar lateral »';
 $('#toggle-sidebar').title=collapsed?'Mostrar propriedades e biblioteca':'Minimizar lateral';
};
initCommandLibrary({storageKey:storageKey+'-library',getProject:()=>project,validateProject,notify,openProject:async data=>{
 if(!await confirmReplace('Abrir comando da biblioteca e substituir a folha?'))return false;
 snapshot();project=data;selected=null;placing=null;wireStart=null;wirePoints=[];stop(false);pickTool('select');$('#project-name').value=project.name;changed();fit();return true;
}});
